import socket

class BotNetClient:
    def __init__(self, host, port)):
        self.host = host
        self.port = port
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM))

    def connect(self):
        try:
            self.socket.connect((self.host), self.port))
            print("Connected to remote server at IP address: {} and port number: {}".format(self.host, self.port))))
            return True
        except Exception as e:
            print("Failed to connect to remote server at IP address: {} and port number: {}".format(self.host, self.port)), "\n", str(e)))
            return False

    def send_command(self, command):
        try:
            self.socket.sendall(command.encode()))
            print("Sent command: {} to remote server".format(command))
            return True
        except Exception as e:
            print("Failed to send command: {} to remote server".format(command)), "\n", str(e)))
            return False

